def add_portfolios(apps, schema_editor):
    Portfolio = apps.get_model("properties", "Portfolio")
    for i, (name, description) in enumerate(STARTING_PORTFOLIOS, start=1):
        Portfolio.objects.get_or_create(name=name, defaults={"description": description, "order": i * 10})


def remove_portfolios(apps, schema_editor):
    apps.get_model("properties", "Portfolio").objects.filter(
        name__in=[n for n, _ in STARTING_PORTFOLIOS], properties__isnull=True).delete()


